INSERT INTO "public"."tools" ("id", "title", "description", "category", "type", "link", "status", "tech_stack", "features", "created_at", "updated_at", "deploy_url", "cover_url") VALUES (7, 'SuQPiano · 3D 钢琴模拟器', '一款基于浏览器的 3D 钢琴模拟器。参数化建模还原三角钢琴，81 键真实音域 + 物理建模音源，支持录制回放与 Piano Roll 音符精细编辑。', '趣味工具', '在线钢琴', 'https://github.com/suqi-bot/SuQPiano', '可用', ARRAY['Three.js','JavaScript (ES Module)','Web Audio API','Canvas'], ARRAY['参数化 3D 三角钢琴：真实尺寸、击弦机/琴弦/踏板/谱架/顶盖','81 键真实音域 + 物理建模加性合成音源（非采样）','电脑键盘 / 鼠标 / 多点触控三种演奏方式','延音踏板、触键力度、混响、八度平移、多视角切换','实时音名瀑布流：展示正在弹奏的音符','录制演奏 + 自动节拍循环回放','Piano Roll 音符编辑器：框选/移动/改时长/删除/复制粘贴/撤销重做','零构建零 CDN：three.js 本地化，完全离线可运行'], '2026-09-03 16:19:23.944934+00', '2026-09-03 16:19:23.944934+00', 'https://suqiweb.cn/SuQPiano/', 'https://suzl-event.oss-cn-beijing.aliyuncs.com/personal-item/SuQPiano.png');
